from itertools import combinations
from math import e
V=('a','b','c')
def effects(S):
 return {'a':1+9*('b' in S),'b':1+9*('a' in S),'c':2}
def f(S):
 tau=effects(S)
 return sum(tau[v] for v in S)
S=set()
for _ in range(2):
 v=max((v for v in V if v not in S),key=lambda v:f(S|{v})-f(S))
 S.add(v)
opt=max((set(p) for p in combinations(V,2)),key=f)
print('Positive, exposure-dependent ITE counterexample with zero diffusion:')
for k in range(3):
 for s in combinations(V,k):
  print(s, f(set(s)))
print('Greedy', sorted(S), f(S), 'Optimum', sorted(opt), f(opt))
print('Ratio', f(S)/f(opt), 'Claimed factor', 1-1/e)
print('Marginal of b from empty:', f({'b'})-f(set()))
print('Marginal of b after a:', f({'a','b'})-f({'a'}))
print('Table 2 relative improvements over baseline:')
for name,base,g,a in [('GoodReads',297.56,330.25,302.17),('Contact',68.12,69.53,66.78),('Email-Eu',735.28,804.28,802.41),('SD-100',138.91,151.59,160.49)]:
 print(name, 'G',round(100*(g/base-1),2),'A',round(100*(a/base-1),2))
PY"
